/**
 * Replaces the global rule set and rename map. Rules are evaluated
top-down and the FIRST matching rule wins. Restricted to admin / SLM /
exec and blocked for view-only sessions.

 * @summary Upsert the global Product Logic rule set + rename map
 */
export const UpdateProductLogicConfigBody = zod.object({
  rules: zod.array(
    zod
      .object({
        id: zod.string(),
        label: zod.string(),
        conditions: zod.array(
          zod
            .object({
              field: zod.enum([
                "product",
                "rawProduct",
                "productFamily",
                "type",
                "termLength",
                "legacyFlag",
                "group",
                "segment",
                "salesRole",
                "quoteType",
                "oppName",
                "funnelStage",
                "changeInMrr",
                "splitTotalPrice",
                "flexFlipAgentStatus",
                "fub_first_purchase_date",
                "user",
                "oppOwner",
              ]),
              op: zod.enum([
                "eq",
                "ne",
                "in",
                "notIn",
                "gt",
                "gte",
                "lt",
                "lte",
                "contains",
                "notContains",
              ]),
              value: zod
                .union([
                  zod.string(),
                  zod.number(),
                  zod.boolean(),
                  zod.array(zod.string()),
                ])
                .describe(
                  "Scalar for `eq`\/`ne`; string array for `in`\/`notIn`.",
                ),
            })
            .describe(
              "A single condition tested by the multiplier engine. All conditions on\na rule must match (logical AND). `legacyFlag` is boolean; the others\nare string-valued with numeric-aware comparison.\n",
            ),
        ),
        assign: zod
          .object({
            kind: zod.enum(["literal", "field"]),
            product: zod
              .string()
              .optional()
              .describe("Set when `kind` is `literal`."),
            field: zod
              .enum(["rawProduct", "productFamily"])
              .optional()
              .describe("Set when `kind` is `field`."),
          })
          .describe(
            'How a matched rule assigns the canonical product. `literal` => a fixed\nproduct name (`product`). `field` => copy the value of a raw opp field\n(`field`), applying the legacy \"Market Based Pricing\" -> \"MBP\"\nnormalization and blank -> \"No Product Selected\" fallback.\n',
          ),
        mrrField: zod
          .enum([
            "changeInMrr",
            "totalMrr",
            "splitTotalPrice",
            "totalPrice",
            "amount",
            "mrr",
            "mrr_added",
            "positive_change_in_mrr",
            "negative_change_in_mrr",
          ])
          .describe(
            "Numeric MRR column standardizeMrr reads for matched rows. The picker\nis source-scoped: feeder columns (changeInMrr…mrr) for `feeder`\nrules, CPD-object columns (mrr_added, positive_change_in_mrr,\nnegative_change_in_mrr) for `cpd` rules. CPD `mrr_added` reads the\nsplitTotalPrice basis ingest copies onto the synthetic row.\n",
          ),
        treatAsClosedWon: zod
          .boolean()
          .describe(
            "When true, rows attributed to this rule's product are treated as\nClosed Won while in Discovery and their effective close date is\npinned to the 1st of the month (generalizes Overage handling).\n",
          ),
        source: zod
          .enum(["feeder", "cpd"])
          .describe(
            "MRR source of the rule, mirroring the compensation engine: `feeder`\n(Salesforce feeder sheet) vs `cpd` (Databricks CPD synthetic object).\nThe chosen `mrrField` must belong to this source — feeder columns for\nfeeder rules, CPD-object columns for CPD rules.\n",
          ),
        isCatchAll: zod
          .boolean()
          .optional()
          .describe("The terminal passthrough rule catching everything else."),
      })
      .describe(
        "One rule in the ordered, FIRST-MATCH product-logic set. All conditions\nmust match (logical AND); the first matching rule wins.\n",
      ),
  ),
  renameMap: zod.array(
    zod
      .object({
        canonical: zod.string(),
        filterName: zod
          .string()
          .optional()
          .describe(
            "Name shown in the product filter (defaults to canonical).",
          ),
        abbreviation: zod
          .string()
          .optional()
          .describe("Short label used in charts\/visualizations."),
        oppNameOverride: zod
          .string()
          .optional()
          .describe("Optional override for the opp name shown in drilldowns."),
      })
      .describe(
        "Display-only rename for a canonical product. The canonical key is never\nchanged (Goals\/Comp depend on it); these only affect presentation.\n",
      ),
  ),
});

