/**
 * Resolves a single goal source into a per-rep, per-product goal set for
the given month (`YYYY-MM`, defaults to current). Products/metrics a
source does not populate are absent (zero downstream). Restricted to
admin / SLM / exec.

 * @summary Resolve goals for one source for a month
 */
export const resolveGoalsQueryMonthRegExp = new RegExp("^\\d{4}-\\d{2}$");

export const ResolveGoalsQueryParams = zod.object({
  source: zod.enum(["financePps", "goalCsv", "softwareGnr", "softwareAcq"]),
  month: zod.coerce.string().regex(resolveGoalsQueryMonthRegExp).optional(),
});

export const ResolveGoalsResponse = zod.object({
  source: zod.enum(["financePps", "goalCsv", "softwareGnr", "softwareAcq"]),
  month: zod.string(),
  goals: zod
    .record(
      zod.string(),
      zod.record(
        zod.string(),
        zod
          .object({
            mrrAddedGoal: zod.number(),
            mrrChurnGoal: zod.number(),
            mrrAddedMinimum: zod.number(),
            mrrChurnMaximum: zod.number(),
          })
          .describe("The four goal metrics resolved per (rep, product)."),
      ),
    )
    .describe(
      "Resolved goals for a month: rep name → product name → metrics. Products\nand metrics a source does not populate are absent (read as zero\ndownstream).\n",
    ),
});

