/**
 * Inserts or updates the per-(month, rep, product) override. Only the
fields present in the body are changed; omitted fields keep their stored
value or the code default. Restricted to admin / SLM / exec.

 * @summary Upsert a single Goals-table row override
 */
export const upsertGoalRowOverrideBodyMonthRegExp = new RegExp(
  "^\\d{4}-\\d{2}$",
);
export const upsertGoalRowOverrideBodyMrrAddedManualMultiplierMin = 0;

export const upsertGoalRowOverrideBodyMrrChurnManualMultiplierMin = 0;

export const upsertGoalRowOverrideBodyERepMultiplierMin = 0;

export const UpsertGoalRowOverrideBody = zod
  .object({
    month: zod.string().regex(upsertGoalRowOverrideBodyMonthRegExp),
    rep: zod.string(),
    product: zod.enum([
      "Showcase",
      "MBP",
      "Zillow Pro",
      "Follow Up Boss",
      "ZMX",
    ]),
    source: zod
      .enum(["financePps", "goalCsv", "softwareGnr", "softwareAcq"])
      .optional()
      .describe("Which goal source drives a row's base goals."),
    mrrAddedManualMultiplier: zod
      .number()
      .min(upsertGoalRowOverrideBodyMrrAddedManualMultiplierMin)
      .optional(),
    mrrChurnManualMultiplier: zod
      .number()
      .min(upsertGoalRowOverrideBodyMrrChurnManualMultiplierMin)
      .optional(),
    loaStatus: zod.string().optional(),
    eRepMultiplier: zod
      .number()
      .min(upsertGoalRowOverrideBodyERepMultiplierMin)
      .nullish()
      .describe(
        "Manual eRep override. Omit to leave unchanged, send null to clear\nback to the Databricks-sourced value, or a number to set it.\n",
      ),
  })
  .describe(
    "Upsert payload for a single Goals-table row override. `month`, `rep` and\n`product` identify the row; the remaining fields are optional and only\nthe provided ones are changed.\n",
  );

export const UpsertGoalRowOverrideResponse = zod.object({
  override: zod
    .object({
      monthYyyymm: zod.string(),
      rep: zod.string(),
      product: zod.string(),
      source: zod.string(),
      mrrAddedManualMultiplier: zod.number(),
      mrrChurnManualMultiplier: zod.number(),
      loaStatus: zod.string(),
      eRepMultiplier: zod.number().nullable(),
      updatedAt: zod.date(),
      updatedByName: zod.string().nullish(),
      updatedByRole: zod.string().nullish(),
    })
    .describe("A persisted Goals-table per-row override."),
});

